// ── Reads CallMeBot credentials from the config server ───────────────────
// Edit credentials at http://localhost:3200

let config = {};
for (const base of ['http://frontend:3200', 'http://localhost:3200']) {
  try {
    const r = await fetch(`${base}/api/config`);
    config = await r.json();
    console.log(`Config loaded from ${base}`);
    break;
  } catch (_) {}
}

const phone  = config.callmebot_phone  || '';
const apiKey = config.callmebot_apikey || '';

if (!phone || !apiKey) {
  return [{ json: {
    ok: false,
    error: 'callmebot_phone or callmebot_apikey not set. Go to http://localhost:3200 to configure.'
  }}];
}

const message    = encodeURIComponent('✅ PA Power Alert — Test message from n8n. WhatsApp notifications are working!');
const endpoint   = `https://api.callmebot.com/whatsapp.php?phone=${phone}&text=${message}&apikey=${apiKey}`;

try {
  const res  = await fetch(endpoint);
  const body = await res.text();

  if (body.toLowerCase().includes('error')) {
    console.error('CallMeBot error:', body);
    return [{ json: { ok: false, error: body.substring(0, 300) } }];
  }

  console.log('✅ Test WhatsApp sent to', phone);
  return [{ json: { ok: true, message: 'Test WhatsApp sent!', to: phone } }];

} catch (e) {
  console.error('Fetch failed:', e.message);
  return [{ json: { ok: false, error: e.message } }];
}
